<script setup lang="ts">
import {ref,onMounted,watch} from 'vue'
import IsolationCallResult from './IsolationCallResult.vue'
import IsolationFollowUps from './IsolationFollowUps.vue'
const callBusy=ref(false),taskBusy=ref(false),callDirty=ref(false),taskDirty=ref(false)
const props=defineProps<{prospectId:number;request:(path:string,body?:any,method?:string)=>Promise<any>}>()
const emit=defineEmits<{saved:[];close:[];book:[];busy:[value:boolean]}>()
const prospect=ref<any>(null),rows=ref<any[]>([]),page=ref(1),count=ref(0),busy=ref(false),error=ref(''),kind=ref('note'),body=ref(''),status=ref('in_progress'),callback=ref('')
const statuses:Record<string,string>={to_contact:'À contacter',in_progress:'En cours',callback:'À rappeler',interested:'Intéressé',not_interested:'Non intéressé',unreachable:'Non joint'}
let requestId=crypto.randomUUID()
function changed(){requestId=crypto.randomUUID()}
async function load(){busy.value=true;error.value='';try{prospect.value=await props.request(`work-queue/${props.prospectId}/`);const data=await props.request(`work-queue/${props.prospectId}/activities/?page=${page.value}`);rows.value=data.results;count.value=data.count}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function save(){if(!prospect.value)return;busy.value=true;error.value='';try{await props.request(`work-queue/${props.prospectId}/activities/`,{request_id:requestId,revision:prospect.value.revision,kind:kind.value,body:body.value,...(kind.value==='qualification'?{status:status.value,callback_at:status.value==='callback'?callback.value:null}:{})});body.value='';callback.value='';changed();page.value=1;await load();emit('saved')}catch(e:any){error.value=e.message}finally{busy.value=false}}
watch([busy,callBusy,taskBusy],()=>emit('busy',busy.value||callBusy.value||taskBusy.value),{flush:'sync'})
function close(){if(busy.value||callBusy.value||taskBusy.value)return;if((body.value||callback.value||callDirty.value||taskDirty.value)&&!window.confirm('Quitter sans enregistrer les saisies ?'))return;emit('close')}
defineExpose({close})
onMounted(load)
</script>
<template><section class="crm-prospect-detail"><h3>Suivi du prospect {{prospect?.name||prospectId}}</h3><p v-if="error" role="alert">{{error}}</p><p v-if="prospect">Résultat commercial : {{prospect.commercial_label}} · Rappel : {{prospect.callback_at?new Date(prospect.callback_at).toLocaleString('fr-FR'):'Aucun'}}</p><p>Les observations commerciales ne modifient pas les résultats techniques des numéros. « Non joint » ne signifie pas « numéro invalide ».</p><IsolationCallResult v-if="prospect" :prospect="prospect" :request="request" :blocked="busy||taskBusy" @busy="callBusy=$event" @dirty="callDirty=$event" @saved="load();emit('saved')" @book="emit('book')"/><IsolationFollowUps :prospect-id="prospectId" :request="request" :blocked="busy||callBusy" @busy="taskBusy=$event" @dirty="taskDirty=$event" @saved="load();emit('saved')"/><form v-if="prospect" @submit.prevent="save" @input="changed" @change="changed"><fieldset :disabled="busy||callBusy||taskBusy"><label>Action<select v-model="kind"><option value="note">Ajouter une note</option><option value="qualification">Renseigner le résultat commercial</option></select></label><template v-if="kind==='qualification'"><label>Résultat<select v-model="status"><option v-for="(label,key) in statuses" :key="key" :value="key">{{label}}</option></select></label><label v-if="status==='callback'">Rappel ISO 8601 avec décalage (ex. 2026-12-01T10:00:00-05:00)<input v-model="callback" required></label><p>Un résultat autre que « À rappeler » retire le rappel courant, dont la date reste conservée dans l’historique.</p></template><label>Note ou justification<textarea v-model="body" required maxlength="3000"></textarea></label><button class="primary">Enregistrer dans l’historique</button></fieldset></form><button class="secondary" :disabled="busy" @click="load">Recharger la fiche et sa version</button><h4>Historique des observations</h4><article v-for="row in rows" :key="row.id"><small>{{new Date(row.created_at).toLocaleString('fr-FR')}} · {{row.author_role}} {{row.author_portal_id}} · {{({note:'Note',qualification:'Qualification',call_result:'Résultat d’appel déclaré',callback_created:'Rappel créé',callback_updated:'Rappel modifié',callback_closed:'Rappel terminé'} as Record<string,string>)[row.kind]||row.kind}}</small><p style="white-space:pre-wrap">{{row.body}}</p><p v-if="row.kind==='call_result'">{{({appointment_booked:'Rendez-vous pris',voicemail:'Répondeur',invalid_number:'Numéro invalide déclaré',disconnected:'Appel coupé',not_interested:'Pas intéressé',callback:'Rappel demandé',unreachable:'Injoignable'} as Record<string,string>)[row.changes.result]}}<span v-if="row.changes.task_id"> · Rappel {{row.changes.task_id}}</span><span v-if="row.changes.appointment_id"> · RDV {{row.changes.appointment_id}}</span></p><p v-if="row.changes.task_id&&row.kind!=='call_result'">Rappel {{row.changes.task_id}} · {{row.changes.after?.due_at||row.changes.due_at}}</p><p v-if="row.kind==='qualification'&&row.changes.after">{{statuses[row.changes.before.status]||row.changes.before.status}} → {{statuses[row.changes.after.status]||row.changes.after.status}} · Rappel : {{row.changes.after.callback_at?new Date(row.changes.after.callback_at).toLocaleString('fr-FR'):'Aucun'}}</p><p v-if="row.kind==='qualification'&&row.changes.before?.callback_at">Ancien rappel : {{new Date(row.changes.before.callback_at).toLocaleString('fr-FR')}}</p></article><p>{{count}} observation(s) · page {{page}}</p><button class="secondary" :disabled="busy||page===1" @click="page--;load()">Précédent</button><button class="secondary" :disabled="busy||page*25>=count" @click="page++;load()">Suivant</button><button class="secondary" :disabled="busy" @click="close">Fermer</button></section></template>
